import { Orm, SchemaBuilder, SnakeCaseNamingStrategy } from '../../src'
import { and, eq, lt, SQL, sql } from 'drizzle-orm'
import { drizzle } from 'drizzle-orm/node-postgres'
import { Pool } from 'pg'
import { Article, Category } from '../fixtures/treeModels'

// A real drizzle instance so the statement is generated by drizzle itself. The pool never
// connects: nothing here runs a query, execution is stubbed at the session boundary.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let db: any
let preparedRows: unknown[] = []
let prepareQuerySpy: jest.SpyInstance
let executeSpy: jest.SpyInstance

beforeAll(() => {
    SchemaBuilder.setNamingStrategy(new SnakeCaseNamingStrategy())
    db = drizzle(new Pool({ host: 'localhost' }), { schema: SchemaBuilder.build() })
})

beforeEach(() => {
    jest.restoreAllMocks()
    preparedRows = []
    jest.spyOn(Orm, 'conn').mockReturnValue(db)
    prepareQuerySpy = jest.spyOn(db.session, 'prepareQuery')
        .mockImplementation(() => ({ execute: async () => preparedRows }))
    executeSpy = jest.spyOn(db, 'execute').mockImplementation(async () => ({ rows: [{ count: '0' }] }))
})

const tree = () => Category.recursiveQuery()
    .anchor(Category.query().where({ parentId: null }))
    .step(Category.query())
    .on((cte, step) => eq(cte.id, step.parentId))

describe('the schema behind a recursive query', () => {
    it('every model gets a twin table named after its CTE', () => {
        expect(SchemaBuilder.getSchema()['categories__recursive']).toBeDefined()
        expect(db.query.categories__recursive).toBeDefined()
    })

    it('the twin is not visible as a model of its own', () => {
        expect(Category.recursiveQuery().cteName).toBe('categories__recursive')
    })
})

describe('statement shape', () => {
    it('defines the CTE and reads from it', () => {
        const text = tree().toSQL().sql.toLowerCase()

        expect(text).toContain('with recursive "categories__recursive" as (')
        expect(text).toContain('union all')
        expect(text).toContain('inner join "categories__recursive" on')
        expect(text).toContain('from "categories__recursive"')
    })

    it('the terms of the CTE keep the database column names', () => {
        const text = tree().toSQL().sql

        expect(text).toContain('"categories"."parent_id" as "parent_id"')
    })

    it('outer conditions apply to the recursion result, not to the source table', () => {
        const text = tree().where({ title: 'x' }).toSQL().sql

        expect(text).toContain('"categories__recursive"."title"')
    })

    it('carries the parameters of both terms, anchor first', () => {
        const query = Category.recursiveQuery()
            .anchor(Category.query().where({ title: 'root' }))
            .step(Category.query().where({ title: 'child' }))
            .on((cte, step) => eq(cte.id, step.parentId))

        expect(query.toSQL().params).toEqual(['root', 'child'])
    })

    it('distinct() switches the union', () => {
        const text = tree().distinct().toSQL().sql.toLowerCase()

        expect(text).toContain('union')
        expect(text).not.toContain('union all')
    })

    it('a raw condition may be passed to on() instead of a callback', () => {
        const query = Category.recursiveQuery()
            .anchor(Category.query())
            .step(Category.query())
            .on(sql`"categories__recursive"."id" = "categories"."parent_id"`)

        expect(query.toSQL().sql).toContain('"categories__recursive"."id" = "categories"."parent_id"')
    })
})

describe('relations load in the same statement', () => {
    it('a to-one relation becomes a lateral join, not a second query', () => {
        const text = Category.recursiveQuery()
            .anchor(Category.query().where({ parentId: null }))
            .step(Category.query())
            .on((cte, step) => eq(cte.id, step.parentId))
            .includeModel(Category, { as: 'parent' })
            .endInclude()
            .toSQL().sql.toLowerCase()

        expect(text).toContain('left join lateral')
        expect(text.match(/select/g)!.length).toBeGreaterThan(1)
    })

    it('a to-many relation is aggregated into the same statement', () => {
        const text = tree()
            .includeModel(Article)
            .endInclude()
            .toSQL().sql.toLowerCase()

        expect(text).toContain('json_agg')
        expect(text).toContain('"articles"')
    })

    it('a filtered include keeps its condition inside the lateral join', () => {
        const { sql: text, params } = tree()
            .includeModel(Article)
            .where({ published: true })
            .endInclude()
            .toSQL()

        expect(text.toLowerCase()).toContain('left join lateral')
        expect(params).toContain(true)
    })

    it('the whole thing is still one statement', () => {
        const text = tree().includeModel(Article).endInclude().toSQL().sql

        expect(text.split(';').filter(Boolean)).toHaveLength(1)
    })
})

describe('values carried down the recursion', () => {
    const withDepth = () => Category.recursiveQuery()
        .anchor(Category.query().select({ extras: { depth: sql`1`.as('depth') } }))
        .step(Category.query().select({
            extras: { depth: sql`"categories__recursive"."depth" + 1`.as('depth') },
        }))

    it('a name that belongs to no table resolves against the collected rows', () => {
        const text = withDepth()
            .on((cte, step) => and(eq(cte.id, step.parentId), lt(cte.depth, 5)) as SQL)
            .toSQL().sql

        expect(text).toContain('"categories__recursive"."depth" <')
        expect(text).toContain('"categories__recursive"."id" = "categories"."parent_id"')
    })

    it('both terms select the computed column under the same name', () => {
        const text = withDepth().on((cte, step) => eq(cte.id, step.parentId)).toSQL().sql

        expect(text.match(/as "depth"/g)).toHaveLength(2)
    })
})

describe('execution', () => {
    it('runs through drizzle so rows come back in the ordinary shape', async () => {
        preparedRows = [
            { id: 1, title: 'root', parentId: null },
            { id: 2, title: 'child', parentId: 1 },
        ]
        const rows = await tree().getAll()

        expect(rows).toHaveLength(2)
        expect(rows[0]).toBeInstanceOf(Category)
        expect(rows[1].title).toBe('child')
    })

    it('asks drizzle for array rows and hands it the relational mapper', async () => {
        await tree().getAll()

        const [, , , isArrayMode, mapper] = prepareQuerySpy.mock.calls[0]
        expect(isArrayMode).toBe(true)
        expect(typeof mapper).toBe('function')
    })

    it('included rows are hydrated into their own model', async () => {
        preparedRows = [{ id: 1, title: 'root', articles: [{ id: 9, title: 'a', categoryId: 1 }] }]
        const [row] = await tree().includeModel(Article).endInclude().getAll()

        expect(row.articles[0]).toBeInstanceOf(Article)
        expect(row.articles[0].title).toBe('a')
    })

    it('getOne() asks for a single row', async () => {
        preparedRows = [{ id: 1, title: 'root' }]
        const row = await tree().getOne()

        expect(row?.title).toBe('root')
    })

    it('getOne() returns null when the recursion yields nothing', async () => {
        expect(await tree().getOne()).toBeNull()
    })

    it('tryGetOne() throws when the recursion yields nothing', async () => {
        await expect(tree().tryGetOne()).rejects.toThrow()
    })

    it('count() counts the rows of the CTE', async () => {
        executeSpy.mockResolvedValue({ rows: [{ count: '7' }] })

        expect(await tree().count()).toBe(7)
    })

    it('count() reports zero for an empty recursion', async () => {
        executeSpy.mockResolvedValue({ rows: [] })

        expect(await tree().count()).toBe(0)
    })

    it('getByPK() filters the recursion result by primary key', async () => {
        preparedRows = [{ id: 3, title: 'found' }]
        const row = await tree().getByPK(3)

        expect(row?.id).toBe(3)
    })
})

describe('misuse', () => {
    it('an anchor without a step is rejected', () => {
        expect(() => Category.recursiveQuery().anchor(Category.query()).toSQL())
            .toThrow(/\.anchor\(query\) and \.step\(query\)/)
    })

    it('a missing join condition is rejected', () => {
        expect(() => Category.recursiveQuery().anchor(Category.query()).step(Category.query()).toSQL())
            .toThrow(/\.on\(/)
    })
})
